public class TraceRmiPlugin : Plugin, InternalTraceRmiService {
	private static readonly int DEFAULT_PORT = 15432;

	static class FallbackTaskMonitor : ConsoleTaskMonitor, CloseableTaskMonitor {
		/* @Override */
		public void close() {
			// Nothing
		}

		/* @Override */
		public void reportError(Throwable e) {
			Msg.error(e.getMessage(), e);
		}
	}

	// @AutoServiceConsumed // via method
	private volatile DebuggerTargetService targetService;
	/* @AutoServiceConsumed */
	private ProgressService progressService;
	/* @SuppressWarnings("unused") */
	private Wiring autoServiceWiring;

	private SocketAddress serverAddress = new InetSocketAddress("127.0.0.1", DEFAULT_PORT);
	private TraceRmiServer server;

	private Set<TraceRmiHandler> handlers = new();
	private Set<DefaultTraceRmiAcceptor> acceptors = new();

	ListenerSet<TraceRmiServiceListener> listeners =
		new(typeof(TraceRmiServiceListener), true);

	private CloseableTaskMonitor fallbackMonitor = new FallbackTaskMonitor();

	public TraceRmiPlugin(PluginTool tool) : base(tool)
    {
		autoServiceWiring = AutoService.wireServicesProvidedAndConsumed(this);
	}

	/* @AutoServiceConsumed */
	public void setTargetService(DebuggerTargetService targetService) {
		this.targetService = targetService;
		record ConnAndTarget(TraceRmiConnection conn, Target target) {}
		List<ConnAndTarget> targets = new();
		lock (handlers) {
			foreach (TraceRmiConnection conn in getAllConnections()) {
				foreach (Target target in conn.getTargets()) {
					targets.add(new ConnAndTarget(conn, target));
				}
			}
		}

		if (targetService != null) {
			foreach (ConnAndTarget cat in targets) {
				targetService.publishTarget(cat.target);
				listeners.invoke().targetPublished(cat.conn, cat.target);
			}
		}
	}

	protected CloseableTaskMonitor createMonitor() {
		if (progressService == null) {
			return fallbackMonitor;
		}
		return progressService.publishTask();
	}

	/* @Override */
	public SocketAddress getServerAddress() {
		if (server != null) {
			// In case serverAddress is ephemeral, get its actual address
			return server.getAddress();
		}
		return serverAddress;
	}

	/* @Override */
	public void setServerAddress(SocketAddress serverAddress) {
		if (server != null) {
			throw new IllegalStateException("Cannot change server address while it is started");
		}
		this.serverAddress = serverAddress;
	}

	/* @Override */
	public void startServer()
    {
		if (server != null) {
			throw new IllegalStateException("Server is already started");
		}
		server = new TraceRmiServer(this, serverAddress);
		server.start();
		listeners.invoke().serverStarted(server.getAddress());
	}

	/* @Override */
	public void stopServer() {
		if (server != null) {
			server.close();
			server = null;
			listeners.invoke().serverStopped();
		}
	}

	/* @Override */
	public bool isServerStarted() {
		return server != null;
	}

	/* @Override */
	/* @SuppressWarnings("resource") */
	public TraceRmiHandler connect(SocketAddress address)
    {
		Socket socket = new Socket();
		socket.connect(address);
		TraceRmiHandler handler = new TraceRmiHandler(this, socket);
		handler.start();
		listeners.invoke().connected(handler, ConnectMode.CONNECT, null);
		return handler;
	}

	/* @Override */
	public DefaultTraceRmiAcceptor acceptOne(SocketAddress address)
    {
		DefaultTraceRmiAcceptor acceptor = new DefaultTraceRmiAcceptor(this, address);
		acceptor.start();
		listeners.invoke().waitingAccept(acceptor);
		return acceptor;
	}

	void addHandler(TraceRmiHandler handler) {
		lock (handlers) {
			handlers.add(handler);
		}
	}

	void removeHandler(TraceRmiHandler handler) {
		lock (handlers) {
			handlers.remove(handler);
		}
	}

	/* @Override */
	public Collection<TraceRmiConnection> getAllConnections() {
		lock (handlers) {
			return List.copyOf(handlers);
		}
	}

	void addAcceptor(DefaultTraceRmiAcceptor acceptor) {
		lock (acceptors) {
			acceptors.add(acceptor);
		}
	}

	void removeAcceptor(DefaultTraceRmiAcceptor acceptor) {
		lock (acceptors) {
			acceptors.remove(acceptor);
		}
	}

	/* @Override */
	public Collection<TraceRmiAcceptor> getAllAcceptors() {
		lock (acceptors) {
			return List.copyOf(acceptors);
		}
	}

	void publishTarget(TraceRmiHandler handler, TraceRmiTarget target) {
		Swing.runIfSwingOrRunLater(() => {
			if (targetService == null) {
				/**
				 * I have no idea how this is happening, given targetService is a required service,
				 * and I don't see any way the rmi server can be started before the services are
				 * wired in. Whatever. I'll have to publish all the targets when the service
				 * appears, I guess.
				 */
				return;
			}
			targetService.publishTarget(target);
			listeners.invoke().targetPublished(handler, target);
		});
	}

	void withdrawTarget(TraceRmiTarget target) {
		Swing.runIfSwingOrRunLater(() => {
			if (targetService == null) {
				// This can happen during tear down.
				return;
			}
			targetService.withdrawTarget(target);
		});
	}

	/* @Override */
	public void addTraceServiceListener(TraceRmiServiceListener listener) {
		listeners.add(listener);
	}

	/* @Override */
	public void removeTraceServiceListener(TraceRmiServiceListener listener) {
		listeners.remove(listener);
	}
}
